        "id": "09-tlm-put-get",
        "title": "Blocking & Non-blocking Put/Get Methods",
        "difficulty": "Intermediate",
        "readTime": "8 min",
        "codeDir": "TLM/TLM_put_method/blocking_put",
        "mainFile": "blocking_put.sv",
        "top": "top",
        "mission": {
          "title": "Transaction Transfer Verification",
          "task": "Trace how componentA calls put_port.put() and componentB implements put_imp.put().",
          "hint": "Blocking calls wait until the transaction is consumed; non-blocking calls return immediately with success boolean."
        },
        "files": {
          "blocking_put.sv": "`include \"uvm_macros.svh\"\nimport uvm_pkg::*;\n\nclass component1 extends uvm_component;\n  `uvm_component_utils(component1)\n\n  int data = 20;\n\n  uvm_blocking_put_port #(int) port;\n\n  function new(input string path = \"Component A\", uvm_component parent = null);\n    super.new(path, parent);\n  endfunction\n\n  virtual function void build_phase(uvm_phase phase);\n    super.build_phase(phase);\n    port  = new(\"port\", this);\n  endfunction\n\n  task main_phase(uvm_phase phase);\n\n    phase.raise_objection(this);\n    port.put(data);\n    `uvm_info(\"PROD\" , $sformatf(\"Data Sent : %0d\", data), UVM_NONE);\n    phase.drop_objection(this);\n\n  endtask\n\nendclass\n////////////////////////////////////////////////\n\nclass component2 extends uvm_component;\n  `uvm_component_utils(component2)\n\n\n  uvm_blocking_put_export #(int) expo;\n  uvm_blocking_put_imp #(int, component2) imp;\n  function new(input string path = \"Component B\", uvm_component parent = null);\n    super.new(path, parent);\n\n  endfunction\n\n virtual function void  build_phase(uvm_phase phase);\n super.build_phase(phase);\n    expo  = new(\"expo\", this);\n    imp = new(\"imp\", this);\n  endfunction\n    \n    task put(int datar);\n    `uvm_info(\"CONS\" , $sformatf(\"Data Rcvd : %0d\", datar), UVM_NONE);\n  endtask\n\nendclass\n\n//////////////////////////////////////////////////////////////////////////////////\n\nclass env extends uvm_env;\n  `uvm_component_utils(env)\n\n  component1 c1;;\n  component2 c2;\n\n\n  function new(input string path = \"env\", uvm_component parent = null);\n    super.new(path, parent);\n  endfunction\n\n  virtual function void build_phase(uvm_phase phase);\n  super.build_phase(phase);\n  c1 = component1::type_id::create(\"c1\",this);\n  c2 = component2::type_id::create(\"c2\", this);\nendfunction\n\n  virtual function void connect_phase(uvm_phase phase);\n   super.connect_phase(phase);\n   c1.port.connect(c2.expo); \n   c2.expo.connect(c2.imp);\n  endfunction\n\nendclass\n\n///////////////////////////////////////////////////\n\nclass test extends uvm_test;\n  `uvm_component_utils(test)\n\n  env e;\n\n  function new(input string path = \"test\", uvm_component parent = null);\n    super.new(path, parent);\n  endfunction\n\n\n  virtual function void build_phase(uvm_phase phase);\n  super.build_phase(phase);\n  e = env::type_id::create(\"e\",this);\nendfunction\n\nendclass\n\n//////////////////////////////////////////////\nmodule tb;\n\ninitial begin\n  run_test(\"test\");\nend\n\nendmodule\n\n\n"
        },
